export const clampZoom=z=>Math.max(.65,Math.min(4,z));
export function focalZoom(center,oldZoom,newZoom,offset){return {x:center.x+offset.x*(1/oldZoom-1/newZoom),y:center.y+offset.y*(1/oldZoom-1/newZoom)};}
export function createView(api){
 const {canvas,root,get,set,save}=api;let space=false,pan=null,touches=new Map(),pinch=null;
 const controls=document.createElement('div');controls.id='view-controls';controls.innerHTML='<button aria-label="Zoom out">−</button><output>100%</output><button aria-label="Zoom in">+</button><button aria-label="Fit hands">fit</button>';root.append(controls);
 function zoomAt(z,x,y){const a=get(),r=canvas.getBoundingClientRect(),next=clampZoom(z),offset={x:(x-r.left-r.width/2)*a.worldWidth/r.width,y:-(y-r.top-r.height/2)*a.worldHeight/r.height};set(next,focalZoom(a.center,a.zoom,next,offset));save();}
 const buttons=controls.querySelectorAll('button');buttons[0].onclick=()=>{const r=canvas.getBoundingClientRect();zoomAt(get().zoom/1.25,r.left+r.width/2,r.top+r.height*.38);};buttons[1].onclick=()=>{const r=canvas.getBoundingClientRect();zoomAt(get().zoom*1.25,r.left+r.width/2,r.top+r.height*.38);};buttons[2].onclick=()=>{api.fit();save();};
 canvas.addEventListener('wheel',e=>{if(api.blocked()||e.altKey)return;e.preventDefault();e.stopImmediatePropagation();api.finish();const a=get();if(e.shiftKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)*.6){set(a.zoom,{x:a.center.x+e.deltaX*a.worldWidth/canvas.clientWidth/a.zoom,y:a.center.y+e.deltaY*a.worldHeight/canvas.clientHeight/a.zoom});save();}else zoomAt(a.zoom*Math.exp(-e.deltaY*(e.ctrlKey?.012:.002)),e.clientX,e.clientY);},{capture:true,passive:false});
 document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA/.test(e.target.tagName))return;if(e.code==='Space'){space=true;e.preventDefault();root.classList.add('panning');}});document.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;root.classList.remove('panning');}});window.addEventListener('blur',()=>{space=false;pan=null;touches.clear();pinch=null;root.classList.remove('panning');});
 const pair=()=>{const p=[...touches.values()];return {x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2,d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)};};
 canvas.addEventListener('pointerdown',e=>{if(api.blocked())return;if(e.pointerType==='touch'){touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size===2&&!api.objectGesture()){api.cancelPaint();api.finish();pinch=pair();e.preventDefault();e.stopImmediatePropagation();canvas.setPointerCapture(e.pointerId);return;}}if(space||e.button===1){api.finish();pan={pointer:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);e.preventDefault();e.stopImmediatePropagation();}},true);
 window.addEventListener('pointermove',e=>{if(api.blocked())return;if(touches.has(e.pointerId))touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pinch&&touches.size===2){e.preventDefault();e.stopImmediatePropagation();const p=pair(),a=get();zoomAt(a.zoom*p.d/Math.max(1,pinch.d),pinch.x,pinch.y);const b=get();set(b.zoom,{x:b.center.x-(p.x-pinch.x)*b.worldWidth/canvas.clientWidth/b.zoom,y:b.center.y+(p.y-pinch.y)*b.worldHeight/canvas.clientHeight/b.zoom});pinch=p;save();}else if(pan?.pointer===e.pointerId){e.preventDefault();e.stopImmediatePropagation();const a=get();set(a.zoom,{x:a.center.x-(e.clientX-pan.x)*a.worldWidth/canvas.clientWidth/a.zoom,y:a.center.y+(e.clientY-pan.y)*a.worldHeight/canvas.clientHeight/a.zoom});pan.x=e.clientX;pan.y=e.clientY;save();}},{capture:true,passive:false});
 function end(e){touches.delete(e.pointerId);if(pinch||pan?.pointer===e.pointerId){e.preventDefault();e.stopImmediatePropagation();if(!touches.size)pinch=null;pan=null;save();}}
 window.addEventListener('pointerup',end,true);window.addEventListener('pointercancel',end,true);
 return {update(){const output=controls.querySelector('output'),text=Math.round(get().zoom*100)+'%';if(output.textContent!==text)output.textContent=text;},zoomAt};
}
